const $ = (s, p = document) => p.querySelector(s);
const $$ = (s, p = document) => [...p.querySelectorAll(s)];
const modal = $('#modal'), content = $('#modal-content');
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read = (key, fallback) => {try{return JSON.parse(localStorage.getItem(key)) ?? fallback}catch{return fallback}};
const save = (key, value) => {try{localStorage.setItem(key, JSON.stringify(value))}catch{toast('Browser storage is unavailable. Your changes last for this visit.')}};
let toastTimer, activeTrade = 'all', selectedJourneyJob = 0, selectedCraft = 'Carpentry', craftChosen = false;
let jobs = [
 {id:1,trade:'Carpentry',icon:'⌁',title:'Give a home its finishing touch.',location:'Hasanpura',distance:'1.2 km',pay:900,hours:'9 am – 5 pm',duration:'2 days',payment:'At the end of each day',employer:'Meera S. · homeowner',description:'Fit two interior doors and repair a wooden window frame. Previous door-fitting experience preferred.',tools:'Bring your hand tools. Materials are provided.',tag:'START TOMORROW'},
 {id:2,trade:'Electrical',icon:'ϟ',title:'Bring a new space to light.',location:'Mansarovar',distance:'2.4 km',pay:1100,hours:'10 am – 6 pm',duration:'3 days',payment:'At the end of each day',employer:'Arjun K. · shop owner',description:'Install lights and switches in a small shop. Work includes checking existing wiring with the owner before starting.',tools:'Bring insulated tools. Fittings are provided.',tag:'3-DAY PROJECT'},
 {id:3,trade:'Painting',icon:'╱',title:'A fresh start. A fresh coat.',location:'Vaishali Nagar',distance:'3.1 km',pay:850,hours:'9 am – 5 pm',duration:'5 days',payment:'At the end of each day',employer:'Neha R. · homeowner',description:'Prepare and paint the walls of two rooms. A helper will be on site. Agree on the surface preparation before work begins.',tools:'Paint, rollers, brushes, and a ladder are provided.',tag:'START THIS WEEK'},
 {id:4,trade:'Plumbing',icon:'⌐',title:'Make the everyday flow better.',location:'Hasanpura',distance:'1.8 km',pay:950,hours:'9 am – 4 pm',duration:'1 day',payment:'On completion, the same day',employer:'Ravi P. · homeowner',description:'Replace a kitchen tap and repair a leaking bathroom pipe. Inspect the problem before agreeing to additional work.',tools:'Bring plumbing tools. Replacement parts are provided.',tag:'ONE-DAY WORK'}
];
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function open(html, cls=''){modal.className=cls;content.innerHTML=html;if(!modal.open)modal.showModal();document.body.style.overflow='hidden';(content.querySelector('input')||$('.modal-close')).focus()}
function close(){modal.close()}
$('.modal-close').onclick=close;
modal.addEventListener('close',()=>{document.body.style.overflow='';window.dispatchEvent(new CustomEvent('gallery-close'));window.speechSynthesis?.cancel()});
modal.addEventListener('click',e=>{if(e.target===modal){const b=modal.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)close()}});
function renderJobs(){const loc=$('#location').value;const visible=jobs.filter(j=>(activeTrade==='all'||j.trade===activeTrade)&&(loc==='all'||j.location===loc));$('#jobs').innerHTML=visible.length?visible.slice(0,6).map(j=>`<article class="job-card"><div class="job-top"><span class="trade-icon" aria-hidden="true">${esc(j.icon)}</span><span class="job-tag">${esc(j.tag)}</span></div><h3>${esc(j.title)}</h3><p class="job-location">${esc(j.trade)} · ${esc(j.location)} · ${esc(j.distance)}</p><p class="pay">₹${j.pay.toLocaleString('en-IN')}<small>/ day</small></p><div class="job-meta"><span>◷ ${esc(j.hours)}</span><span>⌑ ${esc(j.duration)}</span></div><div class="job-bottom"><span>Payment terms included</span><button data-job="${j.id}" aria-label="View ${esc(j.trade)} opportunity">View work <span>↗</span></button></div></article>`).join(''):'<p class="empty-state">No sample opportunities match this selection.<br>Try another trade or hiring point.</p>'}
$$('.filter').forEach(b=>b.onclick=()=>{activeTrade=b.dataset.trade;$$('.filter').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderJobs()});$('#location').onchange=renderJobs;
$('#jobs').onclick=e=>{const b=e.target.closest('[data-job]');if(b)showJob(Number(b.dataset.job))};
function showJob(id){const j=jobs.find(x=>x.id===id),interested=read('artemis-interests',[]).includes(id);open(`<p class="eyebrow">SAMPLE OPPORTUNITY / ${esc(j.trade.toUpperCase())}</p><h2>${esc(j.title)}</h2><p>${esc(j.employer)}<br>⌖ ${esc(j.location)} · ${esc(j.distance)} from the sample hiring point</p><div class="detail-grid"><div><small>PAY PER DAY</small>₹${j.pay.toLocaleString('en-IN')}</div><div><small>WORKING HOURS</small>${esc(j.hours)}</div><div><small>DURATION</small>${esc(j.duration)}</div><div><small>PAYMENT TIMING</small>${esc(j.payment)}</div></div><p>${esc(j.description)}</p><p class="detail-note">${esc(j.tools)}</p><p>Confirm breaks, travel, extra tasks, and the final amount together before starting. This employer and listing are fictional demo content.</p><div class="modal-actions"><button class="button button-dark" id="interest">${interested?'View saved request':'Send demo job request'} <span>↗</span></button><button class="button small-button" id="read-job">Listen to details ♫</button></div><button class="text-button" id="report-job">Something looks wrong? Flag this listing ↗</button>`);$('#interest').onclick=()=>{const ids=read('artemis-interests',[]);ids.push(id);save('artemis-interests',[...new Set(ids)]);$('#interest').textContent='Demo request saved ✓';$('#interest').disabled=true;showAthenaConfirmation(j)};$('#read-job').onclick=()=>{if(!('speechSynthesis'in window))return toast('Read-aloud is unavailable in this browser.');speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(`${j.title}. ${j.trade} in ${j.location}. ${j.pay} rupees per day. ${j.hours}, for ${j.duration}. Payment: ${j.payment}. ${j.description}. ${j.tools}`))};$('#report-job').onclick=()=>{open('<p class="eyebrow">HELP KEEP THE AGORA CLEAR</p><h2>Flag a concern.</h2><p>This demo keeps the report locally. No report is sent to a real moderation team.</p><form id="report-form"><label for="reason">What concerns you?</label><select id="reason"><option>Unclear or suspicious payment</option><option>Incorrect job details</option><option>Employer asking for money</option><option>Other concern</option></select><label for="report-note">Add a note (optional)</label><textarea id="report-note" rows="3" maxlength="500"></textarea><button class="button button-dark">Save demo report ↗</button></form>');$('#report-form').onsubmit=e=>{e.preventDefault();save('artemis-report',{id,reason:$('#reason').value,note:$('#report-note').value});close();toast('Demo report saved on this device.')}}}
function profile(){const p=read('artemis-profile',{trade:selectedCraft});if(craftChosen)p.trade=selectedCraft;open(`<p class="eyebrow">YOUR SKILL IS YOUR INTRODUCTION</p><h2>Your work.<br>Your story.</h2><p>Create a simple card. No résumé needed.<br>This prototype saves your card only in this browser.</p><form id="profile-form"><label for="worker-name">What should people call you?</label><input id="worker-name" name="name" required maxlength="60" autocomplete="given-name" placeholder="Your name" value="${esc(p.name||'')}"><div class="form-row"><div><label for="worker-trade">Your trade</label><select id="worker-trade" name="trade">${['Carpentry','Electrical','Painting','Plumbing','Cleaning','General labour'].map(t=>`<option ${p.trade===t?'selected':''}>${t}</option>`).join('')}</select></div><div><label for="worker-years">Years of experience</label><input id="worker-years" name="years" type="number" min="0" max="70" required placeholder="e.g. 8" value="${esc(p.years??'')}"></div></div><label for="worker-point">Your usual hiring point</label><select id="worker-point" name="point">${['Hasanpura labour chowk','Mansarovar hiring point','Vaishali Nagar'].map(t=>`<option ${p.point===t?'selected':''}>${t}</option>`).join('')}</select><label for="worker-photo">A photo of your work (optional)</label><input class="file-input" id="worker-photo" type="file" accept="image/png,image/jpeg,image/webp"><label for="worker-story">Tell us about your craft (optional)</label><textarea id="worker-story" name="story" rows="2" maxlength="240" placeholder="I fit doors, build furniture, and repair wooden frames…">${esc(p.story||'')}</textarea><button class="button button-dark">Make my work card <span>↗</span></button></form>`);$('#profile-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;const data=Object.fromEntries(new FormData(form));let photo=p.photo||'';const file=$('#worker-photo').files[0];if(file){if(file.size>2000000)return toast('Choose a photo smaller than 2 MB.');photo=await new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>resolve('');r.readAsDataURL(file)})}data.photo=photo;save('artemis-profile',data);craftChosen=false;window.dispatchEvent(new CustomEvent('craft-created'));showCard(data)}}
function showCard(p){open(`<p class="eyebrow">A CRAFT WORTH KNOWING</p><h2>You’re ready<br>to be seen.</h2><div class="saved-card"><p class="eyebrow">ARTEMIS / WORK CARD</p>${p.photo?`<img src="${esc(p.photo)}" alt="Your uploaded work" style="width:100%;height:150px;object-fit:cover;margin-bottom:20px">`:''}<h3>${esc(p.name)}</h3><p>${esc(p.trade)} · ${esc(p.years)} years of experience<br>⌖ ${esc(p.point)}</p>${p.story?`<p>${esc(p.story)}</p>`:''}<p>${esc(read('artemis-availability','Availability not set yet'))}</p></div><p style="margin-top:18px">Saved on this browser. This demo card is not publicly listed.</p><div class="modal-actions"><button class="button button-dark" id="edit-card">Edit my card ↗</button><button class="small-button" id="card-availability">Set availability ↗</button></div>`);$('#edit-card').onclick=profile;$('#card-availability').onclick=availability}
function availability(){open('<p class="eyebrow">LET YOUR NEXT CHAPTER FIND YOU</p><h2>Ready for work?</h2><p>Choose how you want to appear on your demo work card.</p><form id="availability-form"><label for="available-status">Your availability</label><select id="available-status"><option>Available today</option><option>Available tomorrow</option><option>Available this week</option><option>Currently working</option></select><label for="travel">How far can you travel?</label><select id="travel"><option>Within 3 km</option><option>Within 5 km</option><option>Within 10 km</option><option>At my usual hiring point</option></select><button class="button button-dark">Save availability ↗</button></form>');$('#availability-form').onsubmit=e=>{e.preventDefault();save('artemis-availability',`${$('#available-status').value} · ${$('#travel').value}`);const p=read('artemis-profile',null);if(p)showCard(p);else{close();toast('Availability saved. Create a work card to add your skills.')}}}
function hire(){open('<p class="eyebrow">GOOD WORK STARTS WITH CLEAR TERMS</p><h2>Find the hands<br>you need.</h2><p>Create a sample opportunity for this session. Nothing is published to real workers.</p><form id="hire-form"><label for="job-title">What needs doing?</label><input id="job-title" name="title" required maxlength="75" placeholder="e.g. Fit a kitchen cabinet"><div class="form-row"><div><label for="hire-trade">Trade</label><select id="hire-trade" name="trade"><option>Carpentry</option><option>Electrical</option><option>Painting</option><option>Plumbing</option></select></div><div><label for="hire-pay">Pay per day (₹)</label><input id="hire-pay" name="pay" type="number" required min="1" max="100000" placeholder="900"></div></div><label for="hire-location">Area</label><select id="hire-location" name="location"><option>Hasanpura</option><option>Mansarovar</option><option>Vaishali Nagar</option></select><div class="form-row"><div><label for="hire-start">Start time</label><input id="hire-start" name="start" type="time" value="09:00" required></div><div><label for="hire-end">End time</label><input id="hire-end" name="end" type="time" value="17:00" required></div></div><label for="hire-payment">When will you pay?</label><select id="hire-payment" name="payment"><option>At the end of each day</option><option>On completion, the same day</option><option>Weekly, on an agreed day</option></select><label for="hire-description">Tasks, tools, and materials</label><textarea id="hire-description" name="description" required rows="2" maxlength="500" placeholder="Describe the work and what you will provide."></textarea><button class="button button-dark">Add sample opportunity <span>↗</span></button></form>');$('#hire-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));if(d.end<=d.start)return toast('End time must be later than start time.');jobs.unshift({...d,id:Date.now(),pay:Number(d.pay),icon:'✧',distance:'Sample location',hours:`${d.start} – ${d.end}`,duration:'To be agreed',employer:'You · sample employer',tools:'Confirm all tools and materials together before starting.',tag:'YOUR DEMO LISTING'});activeTrade='all';$$('.filter').forEach(x=>{x.classList.toggle('active',x.dataset.trade==='all');x.setAttribute('aria-pressed',String(x.dataset.trade==='all'))});$('#location').value='all';renderJobs();close();$('#opportunities').scrollIntoView({behavior:'smooth'});toast('Sample opportunity added for this visit.')}}
const support={schemes:{title:'Start with<br>official support.',body:'Worker registration can be a starting point for discovering available support. Eligibility and benefits depend on your circumstances and the relevant scheme.',items:['Explore the official e-Shram portal for unorganised workers.','Check your state labour department for construction-worker registration and welfare information.','Ask an authorised support centre if you need help applying.'],link:'https://eshram.gov.in/',label:'Open the official e-Shram portal ↗'},documents:{title:'A little preparation.<br>A clearer next step.',body:'Requirements vary by registration channel. Check the official list before you travel or apply.',items:['Keep your identity and address details ready.','Have access to your mobile number and any required bank details.','Keep existing worker registration details, if you have them.','Use the official portal to confirm exactly what is needed. Do not upload sensitive documents to this prototype.'],link:'https://eshram.gov.in/',label:'Check official registration information ↗'},payment:{title:'Clear terms.<br>A stronger footing.',body:'Before starting work, record the agreed tasks, hours, rate, payment date, and who provides materials. Keep a copy of messages and any payment record.',items:['Clarify whether the amount is per day, per task, or for the entire project.','Agree on extra hours and additional tasks before doing them.','If a dispute arises, consult the relevant local labour authority about the right grievance channel.'],link:'https://labour.gov.in/',label:'Find official Ministry of Labour information ↗'}};
$$('[data-support]').forEach(b=>b.onclick=()=>{const s=support[b.dataset.support];open(`<div class="support-content"><p class="eyebrow">YOUR RIGHTS / A STARTING POINT</p><h2>${s.title}</h2><p>${s.body}</p><ul>${s.items.map(t=>`<li>${t}</li>`).join('')}</ul><a href="${s.link}" target="_blank" rel="noopener noreferrer">${s.label}</a><p style="margin-top:22px;font-size:10px">General signposting for this concept prototype. Check current requirements with the official channel.</p></div>`)})
function credits(){open('<p class="eyebrow">ABOUT THIS CANVAS</p><h2>Myth, material,<br>and human hands.</h2><div class="credit-list"><p>ARTEMIS is an interactive design prototype. All jobs, employers, distances, and worker examples are illustrative. Forms save locally or for this session; they do not contact anyone.</p><p>The mythological artwork was created using OpenAI image generation. Three.js renders an original garden, opening bronze gates, four articulated mythological figures, selectable job stones, and an Athena celebration. The models are procedural sculptures created for this prototype.</p><p><a href="https://zenodo.org/records/21173537" target="_blank" rel="noopener">Torso of a kouros — Scan-the-World</a>, via 3DBigDataSpace / Zenodo. Licensed <a href="https://creativecommons.org/licenses/by-nc-sa/4.0/" target="_blank" rel="noopener">CC BY-NC-SA 4.0</a>. Presented with altered scale, lighting, and material for this noncommercial concept. Model retained under the same license.</p><p>Typography: Cormorant Garamond and DM Sans via Google Fonts. Three.js: MIT license.</p></div>')}
$$('[data-action]').forEach(b=>b.onclick=()=>{if(b.dataset.action==='profile'&&b.closest('.site-header')){const p=read('artemis-profile',null);return p?showCard(p):profile()}return {profile,hire,availability,credits}[b.dataset.action]?.()});
$$('[data-story]').forEach(b=>b.onclick=()=>{const index=Number(b.dataset.story);if(index===1)profile();if(index===2){$('#opportunities').scrollIntoView({behavior:'smooth'});toast('Choose your area and trade to explore sample opportunities.')}if(index===3)$('#support').scrollIntoView({behavior:'smooth'})});
let paused=matchMedia('(prefers-reduced-motion: reduce)').matches;
function setMotion(){document.body.classList.toggle('no-motion',paused);$('#motion-toggle').setAttribute('aria-pressed',String(paused));$('#motion-toggle').innerHTML=`Motion <span>${paused?'○':'◉'}</span>`;$('#motion-toggle').title=paused?'Resume animation':'Pause animation';window.dispatchEvent(new CustomEvent('motion-change',{detail:paused}))}
$('#motion-toggle').onclick=()=>{paused=!paused;setMotion()};matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>{paused=e.matches;setMotion()});setMotion();
renderJobs();

function showAthenaConfirmation(job){
 open(`<canvas id="celebration-canvas" class="celebration-canvas" aria-label="Athena raises a laurel in a glowing three dimensional celebration"></canvas><div class="celebration-copy"><p class="eyebrow">ATHENA / A NEW CHAPTER</p><h2>Glory to<br><em>your next step.</em></h2><p>Your demo request is saved.<br>May wisdom guide the work ahead.</p><div class="request-receipt">${esc(job.trade)} · ${esc(job.location)}<br>₹${job.pay.toLocaleString('en-IN')} per day · ${esc(job.hours)}</div><button class="button button-light" id="athena-done">Continue my journey <span>↗</span></button><p class="prototype-note">Prototype confirmation only. No employer has been contacted and no job is confirmed.</p></div><span class="celebration-legend">ATHENA · WISDOM, CRAFT & COURAGE</span>`,'athena-celebration');
 $('#athena-done').onclick=close;
 window.dispatchEvent(new CustomEvent('request-celebration',{detail:$('#celebration-canvas')}));
}
function updateJourneyJob(index){selectedJourneyJob=index;const job=jobs.find(j=>j.id===index+1);if(!job)return;$('#journey-job-title').textContent=`${job.trade} in ${job.location}`;$('#journey-job-pay').innerHTML=`₹${job.pay.toLocaleString('en-IN')} <small>/ day</small>`;$('#journey-job-time').textContent=`${job.hours} · ${job.duration}`;}
window.addEventListener('stone-selected',e=>updateJourneyJob(e.detail));
$('#journey-view-job').onclick=()=>showJob(selectedJourneyJob+1);
$$('[data-craft]').forEach(b=>b.onclick=()=>{selectedCraft=b.dataset.craft;craftChosen=true;$$('[data-craft]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});window.dispatchEvent(new CustomEvent('craft-select',{detail:selectedCraft}))});
$$('[data-promise]').forEach(b=>b.onclick=()=>{const on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(on));$('.promise-check',b).textContent=on?'✓':'+';window.dispatchEvent(new CustomEvent('promise-change',{detail:$$('[data-promise][aria-pressed="true"]').length}))});
$('#review-promise').onclick=()=>{const j=jobs.find(x=>x.id===selectedJourneyJob+1);open(`<p class="eyebrow">HERMES / THE CLEAR AGREEMENT</p><h2>Before the work,<br>the understanding.</h2><p>This sample agreement brings the essentials into one place. Both people should discuss and confirm them before starting.</p><div class="detail-grid"><div><small>THE WORK</small>${esc(j.trade)} · ${esc(j.duration)}</div><div><small>THE HOURS</small>${esc(j.hours)}</div><div><small>THE PAY</small>₹${j.pay.toLocaleString('en-IN')} per day</div><div><small>PAYMENT TIMING</small>${esc(j.payment)}</div></div><p>${esc(j.description)}</p><p class="detail-note">${esc(j.tools)}</p><p>Ask about breaks, travel, additional tasks, and how extra hours will be paid. A clear listing is not a payment guarantee.</p><button class="button button-dark" id="agreement-work" style="margin-top:24px;width:100%">Review this opportunity <span>↗</span></button>`);$('#agreement-work').onclick=()=>showJob(j.id)};
